package com.railway.model;
public class User {private long id;private String fullName,email,phone,role;public User(){} public User(long id,String n,String e,String p,String r){this.id=id;fullName=n;email=e;phone=p;role=r;} public long getId(){return id;}public void setId(long v){id=v;}public String getFullName(){return fullName;}public void setFullName(String v){fullName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getRole(){return role;}public void setRole(String v){role=v;} }
